<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu-like Desktop</title>
<style>
  * { box-sizing: border-box; }
  html, body {
    margin: 0; padding: 0; height: 100%; overflow: hidden;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }
  #desktop {
    position: fixed; inset: 0;
    background:
      radial-gradient(circle at 20% 30%, rgba(107, 33, 168, 0.35) 0%, transparent 40%),
      radial-gradient(circle at 80% 70%, rgba(37, 99, 235, 0.25) 0%, transparent 40%),
      linear-gradient(135deg, #0f0f13 0%, #1a1a24 100%);
    color: #eee;
  }
  #taskbar {
    position: absolute; top: 0; left: 0; right: 0; height: 44px;
    display: flex; align-items: center; gap: 10px; padding: 0 12px;
    background: rgba(30, 30, 36, 0.92);
    border-bottom: 1px solid rgba(255,255,255,0.08);
    backdrop-filter: blur(10px);
    z-index: 1000;
  }
  .launcher {
    display: flex; align-items: center; gap: 8px;
    padding: 6px 12px; border-radius: 8px; border: none;
    background: transparent; color: #eee; font-size: 14px; cursor: pointer;
  }
  .launcher:hover { background: rgba(255,255,255,0.1); }
  .launcher::before {
    content: ""; display: inline-block; width: 18px; height: 18px;
    border-radius: 3px;
  }
  #open-files::before {
    background: #f59e0b;
    box-shadow: inset 0 -6px 0 rgba(0,0,0,0.15);
  }
  #open-notepad::before {
    background: #10b981;
    box-shadow: inset 0 -6px 0 rgba(0,0,0,0.15);
  }

  .window {
    position: absolute;
    min-width: 360px; min-height: 240px;
    width: 640px; height: 420px;
    background: #1e1e24;
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 10px;
    box-shadow: 0 20px 50px rgba(0,0,0,0.55);
    display: flex; flex-direction: column;
    overflow: hidden;
  }
  .win-title {
    height: 38px;
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 12px;
    background: linear-gradient(to bottom, #2d2d36, #25252c);
    border-bottom: 1px solid rgba(255,255,255,0.08);
    cursor: move; user-select: none;
  }
  .win-title span { font-weight: 600; font-size: 13px; color: #ddd; }
  .win-close {
    width: 14px; height: 14px; border-radius: 50%; border: none;
    background: #ff5f57; cursor: pointer;
    box-shadow: inset 0 0 0 0.5px rgba(0,0,0,0.2);
  }
  .win-close:hover { background: #ff453a; }
  .win-body {
    flex: 1; overflow: auto; position: relative;
  }

  /* Files app */
  #files-pathbar {
    display: flex; align-items: center; gap: 8px;
    padding: 10px 12px; background: #15151a;
    border-bottom: 1px solid rgba(255,255,255,0.08);
  }
  #files-path {
    flex: 1; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    color: #9ca3af; font-size: 13px;
  }
  #files-up {
    padding: 5px 10px; border-radius: 6px; border: none;
    background: #2d2d36; color: #eee; font-size: 12px; cursor: pointer;
  }
  #files-up:disabled { opacity: 0.4; cursor: not-allowed; }
  #files-list {
    display: flex; flex-wrap: wrap; gap: 12px; padding: 16px;
  }
  .fs-item {
    width: 88px; display: flex; flex-direction: column; align-items: center;
    gap: 6px; padding: 10px 6px; border-radius: 8px; cursor: pointer;
    text-align: center; font-size: 12px; color: #e5e5e5;
  }
  .fs-item:hover { background: rgba(255,255,255,0.08); }
  .fs-icon {
    width: 44px; height: 36px; border-radius: 4px; position: relative;
  }
  .fs-item[data-type="dir"] .fs-icon {
    background: #f59e0b;
    box-shadow: inset 0 -8px 0 rgba(0,0,0,0.15);
  }
  .fs-item[data-type="file"] .fs-icon {
    background: #e5e7eb; color: #374151;
  }
  .fs-item[data-type="file"] .fs-icon::after {
    content: ""; position: absolute; top: 0; right: 0;
    width: 12px; height: 12px;
    background: #1e1e24;
    border-bottom-left-radius: 4px;
  }

  /* Notepad app */
  #notepad-app {
    display: flex; flex-direction: column; height: 100%;
  }
  #tabs {
    display: flex; align-items: center; gap: 4px;
    padding: 6px 8px 0; background: #15151a;
    border-bottom: 1px solid rgba(255,255,255,0.08);
    overflow-x: auto;
  }
  .tab {
    display: flex; align-items: center; gap: 8px;
    padding: 7px 12px; border-radius: 8px 8px 0 0;
    background: #2a2a32; color: #bbb; font-size: 13px; cursor: pointer;
    white-space: nowrap; user-select: none;
  }
  .tab.active { background: #1e1e24; color: #eee; }
  .tab-close {
    width: 14px; height: 14px; line-height: 14px; text-align: center;
    border-radius: 50%; font-size: 11px; color: #bbb;
  }
  .tab-close:hover { background: rgba(255,255,255,0.15); color: #fff; }
  #new-tab {
    padding: 5px 10px; border-radius: 6px; border: none;
    background: #2d2d36; color: #eee; font-size: 16px; cursor: pointer;
  }
  #new-tab:hover { background: #3a3a44; }
  #editor-wrap {
    flex: 1; position: relative;
  }
  #editor {
    position: absolute; inset: 0; width: 100%; height: 100%;
    padding: 12px; border: none; outline: none; resize: none;
    background: #1e1e24; color: #e5e5e5; font-size: 14px; line-height: 1.5;
  }
</style>
</head>
<body>
<div id="desktop">
  <div id="taskbar">
    <button id="open-files" class="launcher">Files</button>
    <button id="open-notepad" class="launcher">Notepad</button>
  </div>

  <div id="files-window" class="window" style="display:none;">
    <div class="win-title">
      <span>Files</span>
      <button class="win-close" aria-label="Close"></button>
    </div>
    <div class="win-body">
      <div id="files-pathbar">
        <span id="files-path">/</span>
        <button id="files-up">Up</button>
      </div>
      <div id="files-list"></div>
    </div>
  </div>

  <div id="notepad-window" class="window" style="display:none;">
    <div class="win-title">
      <span>Text Editor</span>
      <button class="win-close" aria-label="Close"></button>
    </div>
    <div class="win-body">
      <div id="notepad-app">
        <div id="tabs">
          <!-- tabs + #new-tab -->
        </div>
        <div id="editor-wrap">
          <textarea id="editor" spellcheck="false"></textarea>
        </div>
      </div>
    </div>
  </div>
</div>

<script>
(function() {
  'use strict';

  /* ---------- Window management ---------- */
  let zBase = 100;
  const desktop = document.getElementById('desktop');
  const windows = document.querySelectorAll('.window');

  function bringToFront(win) {
    zBase++;
    win.style.zIndex = zBase;
  }

  function centerWindow(win) {
    const dW = desktop.clientWidth;
    const dH = desktop.clientHeight;
    const wW = Math.min(win.offsetWidth || 640, dW - 40);
    const wH = Math.min(win.offsetHeight || 420, dH - 40);
    const left = Math.max(10, (dW - wW) / 2);
    const top = Math.max(10 + 44, (dH - wH) / 2);
    win.style.left = left + 'px';
    win.style.top = top + 'px';
  }

  function openWindow(id) {
    const win = document.getElementById(id);
    if (!win) return;
    win.style.display = 'flex';
    bringToFront(win);
    if (!win.dataset.placed) {
      centerWindow(win);
      win.dataset.placed = '1';
    }
  }

  function closeWindow(win) {
    win.style.display = 'none';
  }

  document.querySelectorAll('.win-close').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      closeWindow(btn.closest('.window'));
    });
  });

  windows.forEach(win => {
    win.addEventListener('mousedown', () => bringToFront(win));
  });

  /* Dragging */
  let dragWin = null, dragOX = 0, dragOY = 0;
  document.querySelectorAll('.win-title').forEach(title => {
    title.addEventListener('mousedown', e => {
      if (e.target.closest('.win-close')) return;
      dragWin = title.closest('.window');
      const rect = dragWin.getBoundingClientRect();
      dragOX = e.clientX - rect.left;
      dragOY = e.clientY - rect.top;
      e.preventDefault();
    });
  });
  window.addEventListener('mousemove', e => {
    if (!dragWin) return;
    let nx = e.clientX - dragOX;
    let ny = e.clientY - dragOY;
    nx = Math.max(0, Math.min(nx, desktop.clientWidth - 80));
    ny = Math.max(44, Math.min(ny, desktop.clientHeight - 40));
    dragWin.style.left = nx + 'px';
    dragWin.style.top = ny + 'px';
  });
  window.addEventListener('mouseup', () => dragWin = null);

  document.getElementById('open-files').addEventListener('click', () => {
    openWindow('files-window');
    renderFiles();
  });
  document.getElementById('open-notepad').addEventListener('click', () => {
    openWindow('notepad-window');
    renderNotepad();
  });

  /* ---------- Files app ---------- */
  const fs = {
    '/': [
      {name:'bin', type:'dir'},
      {name:'etc', type:'dir'},
      {name:'home', type:'dir'},
      {name:'usr', type:'dir'},
      {name:'var', type:'dir'},
      {name:'readme.txt', type:'file'}
    ],
    '/bin': [
      {name:'bash', type:'file'},
      {name:'ls', type:'file'},
      {name:'cat', type:'file'}
    ],
    '/etc': [
      {name:'hosts', type:'file'},
      {name:'passwd', type:'file'},
      {name:'fstab', type:'file'}
    ],
    '/home': [
      {name:'user', type:'dir'}
    ],
    '/home/user': [
      {name:'Documents', type:'dir'},
      {name:'Downloads', type:'dir'},
      {name:'Pictures', type:'dir'},
      {name:'todo.txt', type:'file'}
    ],
    '/home/user/Documents': [
      {name:'resume.pdf', type:'file'},
      {name:'notes.txt', type:'file'}
    ],
    '/home/user/Downloads': [
      {name:'app.deb', type:'file'},
      {name:'archive.zip', type:'file'}
    ],
    '/home/user/Pictures': [
      {name:'wallpaper.png', type:'file'},
      {name:'avatar.jpg', type:'file'}
    ],
    '/usr': [
      {name:'bin', type:'dir'},
      {name:'share', type:'dir'}
    ],
    '/usr/bin': [
      {name:'gcc', type:'file'},
      {name:'python3', type:'file'}
    ],
    '/usr/share': [
      {name:'icons', type:'dir'}
    ],
    '/usr/share/icons': [
      {name:'theme.index', type:'file'}
    ],
    '/var': [
      {name:'log', type:'dir'}
    ],
    '/var/log': [
      {name:'syslog', type:'file'}
    ]
  };

  let currentPath = '/';

  function parentPath(p) {
    if (p === '/') return null;
    const parts = p.replace(/^\/+/, '').split('/').filter(Boolean);
    parts.pop();
    return parts.length ? '/' + parts.join('/') : '/';
  }

  function childPath(parent, name) {
    return parent === '/' ? '/' + name : parent + '/' + name;
  }

  function renderFiles() {
    document.getElementById('files-path').textContent = currentPath;
    const upBtn = document.getElementById('files-up');
    upBtn.disabled = currentPath === '/';

    const list = document.getElementById('files-list');
    list.innerHTML = '';
    const items = fs[currentPath] || [];
    items.forEach(item => {
      const el = document.createElement('div');
      el.className = 'fs-item';
      el.dataset.type = item.type;
      el.dataset.name = item.name;
      el.innerHTML = '<div class="fs-icon"></div><span></span>';
      el.querySelector('span').textContent = item.name;
      if (item.type === 'dir') {
        el.addEventListener('dblclick', () => {
          currentPath = childPath(currentPath, item.name);
          renderFiles();
        });
      }
      list.appendChild(el);
    });
  }

  document.getElementById('files-up').addEventListener('click', () => {
    const p = parentPath(currentPath);
    if (p !== null) {
      currentPath = p;
      renderFiles();
    }
  });

  /* ---------- Notepad app ---------- */
  const STORAGE_KEY = 'notepad-tabs-v1';
  let notepad = { tabs: [], activeId: null };

  function loadNotepad() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) notepad = JSON.parse(raw);
    } catch (e) { notepad = { tabs: [], activeId: null }; }
    if (!notepad.tabs || !notepad.tabs.length) {
      createTab(false);
    }
    if (!notepad.activeId || !notepad.tabs.find(t => t.id === notepad.activeId)) {
      notepad.activeId = notepad.tabs[0].id;
    }
  }

  function saveNotepad() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(notepad));
    } catch (e) {}
  }

  function makeId() {
    return 'tab-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7);
  }

  function titleForContent(text) {
    const first = (text || '').split('\n')[0].trim();
    return first ? first.slice(0, 18) + (first.length > 18 ? '…' : '') : 'Untitled';
  }

  function createTab(save = true) {
    const id = makeId();
    const tab = { id, content: '' };
    notepad.tabs.push(tab);
    notepad.activeId = id;
    if (save) saveNotepad();
    return tab;
  }

  function closeTab(id, event) {
    if (event) event.stopPropagation();
    const idx = notepad.tabs.findIndex(t => t.id === id);
    if (idx === -1) return;
    notepad.tabs.splice(idx, 1);
    if (notepad.activeId === id) {
      notepad.activeId = notepad.tabs[Math.max(0, idx - 1)]?.id || notepad.tabs[0]?.id || null;
    }
    if (!notepad.tabs.length) createTab(false);
    saveNotepad();
    renderNotepad();
  }

  function switchTab(id) {
    if (!notepad.tabs.find(t => t.id === id)) return;
    notepad.activeId = id;
    saveNotepad();
    renderNotepad();
  }

  function updateActiveContent(text) {
    const tab = notepad.tabs.find(t => t.id === notepad.activeId);
    if (!tab) return;
    tab.content = text;
    saveNotepad();
    renderTabTitles();
  }

  function renderTabTitles() {
    document.querySelectorAll('.tab').forEach(el => {
      const id = el.dataset.id;
      const tab = notepad.tabs.find(t => t.id === id);
      if (tab) {
        const titleSpan = el.querySelector('.tab-title');
        if (titleSpan) titleSpan.textContent = titleForContent(tab.content);
      }
    });
  }

  function renderNotepad() {
    const tabsEl = document.getElementById('tabs');
    tabsEl.innerHTML = '';

    notepad.tabs.forEach(tab => {
      const btn = document.createElement('div');
      btn.className = 'tab' + (tab.id === notepad.activeId ? ' active' : '');
      btn.dataset.id = tab.id;
      const title = document.createElement('span');
      title.className = 'tab-title';
      title.textContent = titleForContent(tab.content);
      const close = document.createElement('span');
      close.className = 'tab-close';
      close.textContent = '×';
      close.addEventListener('click', e => closeTab(tab.id, e));
      btn.appendChild(title);
      btn.appendChild(close);
      btn.addEventListener('click', e => {
        if (e.target === close || e.target.classList.contains('tab-close')) return;
        switchTab(tab.id);
      });
      tabsEl.appendChild(btn);
    });

    const newBtn = document.createElement('button');
    newBtn.id = 'new-tab';
    newBtn.title = 'New tab';
    newBtn.textContent = '+';
    newBtn.addEventListener('click', () => {
      createTab();
      renderNotepad();
    });
    tabsEl.appendChild(newBtn);

    const editor = document.getElementById('editor');
    const active = notepad.tabs.find(t => t.id === notepad.activeId) || notepad.tabs[0];
    editor.value = active ? active.content : '';
  }

  const editor = document.getElementById('editor');
  editor.addEventListener('input', () => updateActiveContent(editor.value));

  /* ---------- Init ---------- */
  loadNotepad();
  renderNotepad();
})();
</script>
</body>
</html>
